\begin{tikzpicture}[font=\sffamily, scale=1]
    % Coordinates and angles
    \def\ang{30}
    \coordinate (O) at (0,0);
    \coordinate (A) at (5,0);
    \coordinate (B) at (5,{5*tan(\ang)});
    \coordinate (P) at (5.5,{5*tan(\ang)}); % Pulley center
    \def\rPulley{0.5}

    % Draw inclined plane
    \draw[thick] (O) -- (A) -- (B) -- cycle;

    % Surface hatching underneath the base
    \surface{(0,0)}{(5,0)}{-1}
    \surface{(5,0)}{(5,{5*tan(\ang)})}{-1} % Wait, surface macro takes two points. Let's do it manually for the incline.

    % Incline hatching (hypotenuse from O to B)
    \foreach \t in {0.5, 1.0, ..., 4.5} {
        \draw[thick] (\t,{ \t*tan(\ang) }) -- ++(-60:0.3);
    }

    % Angle arc
    \draw (1,0) arc (0:\ang:1);
    \node at (1.4,0.3) {$\ang^\circ$};

    % 4.0 kg Block on the incline
    % Let's place the center of the block at some distance along the incline
    \begin{scope}[shift={(2,{2*tan(\ang)} )}, rotate=\ang]
        % Block dimensions
        \def\bw{1.2}
        \def\bh{0.8}
        \draw[thick, fill=white] (-\bw/2, 0) rectangle (\bw/2, \bh);
        % Center of mass dot
        \fill (0,\bh/2) circle (1.5pt);
        % String attachment at top edge
        \coordinate (StringAttach) at (\bw/2, \bh/2);
    \end{scope}

    % Re-calculate string attach coordinate in global system
    % Center was at (2, 2*tan(30)), rotated by 30.
    % Let's define it more precisely using calc
    \coordinate (BlockCenter) at ($(O) + (\ang:2) + (0,\bh/2)$); % roughly
    % Actually let's use a simpler geometry construction for the block
    % Distance along incline = 2.5
    \coordinate (BasePos) at ({2.5*cos(\ang)}, {2.5*sin(\ang)});
    \begin{scope}[shift={(BasePos)}, rotate=\ang]
        \draw[thick, fill=white] (-0.6,0) rectangle (0.6,0.8);
        \coordinate (TopEdge) at (0.6, 0.4);
    \end{scope}

    % Transform TopEdge to global coordinates (approximate for drawing string)
    % Better yet, let's draw the string directly:
    % From block up to pulley
    \coordinate (SBlock) at ($(2.5*cos(\ang), 2.5*sin(\ang)) + (-\ang:0) + (0.6*cos(\ang)-0.4*sin(\ang), 0.6*sin(\ang)+0.4*cos(\ang)) $); 
    % Let's just hardcode visual points since it's a schematic diagram
    \coordinate (BlockTop) at ({2.5*cos(\ang) + 0.4*sin(\ang)}, {2.5*sin(\ang) + 0.4*cos(\ang)}); 
    % Wait, let's let TikZ handle it via rotation:
    \coordinate (StringStart) at ($(2.5*cos(\ang), 2.5*sin(\ang)) + (\ang:0.6) + (\ang+90:0.4)$);

    % Pulley at (5, {5*tan(30)}) + radius in y direction
    \coordinate (PulleyCenter) at ({5 + \rPulley}, {5*tan(\ang)});
    % Draw pulley support
    \draw[thick] (5,{5*tan(\ang)}) -- (PulleyCenter);
    \draw[thick, fill=white] (PulleyCenter) circle (\rPulley);
    \fill (PulleyCenter) circle (1pt);

    % Draw String
    % From block up-right to pulley edge, then down to hanging mass
    \coordinate (PulleyEdgeTop) at ($(PulleyCenter) + (0, \rPulley)$);
    \coordinate (PulleyEdgeRight) at ($(PulleyCenter) + (\rPulley, 0)$);

    % Let's adjust Pulley position to sit neatly at corner B
    \coordinate (Puv) at ($(B) + (\rPulley, 0)$); % Wait, corner B is (5, 5*tan(30))
    \draw[thick] (B) -- ++(0.5,0) coordinate(PCC);
    \node[above] at ($(PCC)+(0,0.5)$) {};

    % Redefine pulley cleanly
    \coordinate (P) at ($(5,{5*tan(\ang)}) + (\rPulley, 0)$);
    % Actually, standard O-level diagram: pulley at apex B
    \draw[thick, fill=white] ($(B)+({\rPulley},{-\rPulley})$) circle (\rPulley); % wait

    % Let's do a standard clear pulley at the vertex B
    \begin{scope}[shift={(B)}]
        \draw[thick, fill=white] (0, \rPulley) circle (\rPulley);
        \coordinate (Ttop) at (0, {2*\rPulley});
        \coordinate (Tright) at (\rPulley, \rPulley);
    \end{scope}

    % Block reference point for string
    % Let's place block at distance 2 along the incline
    \def\dist{2.2}
    \coordinate (Blk) at ({\dist*cos(\ang)}, {\dist*sin(\ang)});
    \begin{scope}[shift={(Blk)}, rotate=\ang]
        \coordinate (StrPt) at (0.6, 0.4);
    \end{scope}
    % Transform StrPt manually to global:
    \coordinate (GlobalStrPt) at ({{\dist*cos(\ang)} + 0.6*cos(\ang) - 0.4*sin(\ang)}, {{\dist*sin(\ang)} + 0.6*sin(\ang) + 0.4*cos(\ang)});

    % Draw string from block to pulley top
    \draw[thick] (GlobalStrPt) -- ($(B)+(0,{2*\rPulley})$); 
    % Wait, string should go to the tangent of pulley
    \draw[thick] ($(B)+(0,{2*\rPulley})$) -- ($(B)+(\rPulley, \rPulley)$);
    \draw[thick] ($(B)+(\rPulley, \rPulley)$) -- ++(0,-2); % hanging mass string

    % Hanging mass
    \coordinate (HMass) at ($(B)+(\rPulley, \rPulley) + (0,-2)$);
    \draw[thick, fill=white] ($(HMass)+(-0.5,-0.8)$) rectangle ($(HMass)+(0.5,0)$);
    \node at (HMass) {3.0 kg};

    % Draw the 4.0 kg block again properly aligned
    \begin{scope}[shift={(Blk)}, rotate=\ang]
        \draw[thick, fill=white] (-0.6, 0) rectangle (0.6, 0.8);
        \node at (0, 0.4) {4.0 kg};
    \end{scope}

    % Fig label below
    \node[below] at (2.5, -0.8) {Fig. 1.1};

\end{tikzpicture}

