    \begin{scope}[shift={(Blk)}, rotate=30]
        \draw[thick, fill=white] (-0.6, 0) rectangle (0.6, 0.8);
        \node at (0, 0.4) {4.0 kg};
        % Coordinate relative to block for string attachment
        \coordinate (StrPt) at (0.6, 0.4);
    \end{scope}

    % Calculate global position of string attachment on block
    \coordinate (GlobalStrPt) at ({{\dist*cos(30)} + 0.6*cos(30) - 0.4*sin(30)}, {{\dist*sin(30)} + 0.6*sin(30) + 0.4*cos(30)});

    % Pulley tangent points for string
    \coordinate (PTop) at ($(PulleyCenter) + (0, \rPulley)$);
    \coordinate (PRight) at ($(PulleyCenter) + (\rPulley, 0)$);

    % Draw String
    \draw[thick] (GlobalStrPt) -- (PTop);
    \draw[thick] (PRight) -- ++(0,-2.2);

    % Hanging mass (3.0 kg)
    \coordinate (HMass) at ($(PRight) + (0,-2.2)$);
    \begin{scope}[shift={(HMass)}]
        \draw[thick, fill=white] (-0.5, -0.8) rectangle (0.5, 0);
        \node at (0, -0.4) {3.0 kg};
    \end{scope}

    % Fig label below
    \node[below] at (2.5, -0.6) {Fig. 1.1};

\end{tikzpicture}

